import random
from collections import deque

n = 19
min_edges = 28

def girth(graph):
    """Compute girth of graph. Return infinity if acyclic."""
    best = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if v == parent[u]:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                else:
                    # found cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
        if best == 3:  # early exit
            return 3
    return best if best != float('inf') else float('inf')

def is_3colorable(graph):
    colors = [-1] * n
    def dfs(v):
        if v == n:
            return True
        for c in range(3):
            ok = True
            for u in graph[v]:
                if colors[u] == c:
                    ok = False
                    break
            if ok:
                colors[v] = c
                if dfs(v + 1):
                    return True
                colors[v] = -1
        return False
    return dfs(0)

