from collections import deque

n = 19
min_edges = 28

# Pre-assign colors to ensure 3-colorability
colors = [0]*7 + [1]*6 + [2]*6
print("Colors:", colors)

# Valid edges: between different colors
valid_edges = []
for i in range(n):
    for j in range(i+1, n):
        if colors[i] != colors[j]:
            valid_edges.append((i, j))

print("Number of valid edges:", len(valid_edges))

def girth(graph):
    best = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if v == parent[u]:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
        if best == 3:
            return 3
    return best if best != float('inf') else float('inf')

# Try random greedy with multiple restarts
random.seed(42)
best_edges = 0
best_graph = None

for restart in range(5000):
    graph = [set() for _ in range(n)]
    edges = []

    # Shuffle valid edges
    shuffled = valid_edges[:]
    random.shuffle(shuffled)

    for u, v in shuffled:
        graph[u].add(v)
        graph[v].add(u)

        g = girth(graph)
        if g < 7:
            graph[u].remove(v)
            graph[v].remove(u)
        else:
            edges.append((u, v))
            if len(edges) >= min_edges:
                break

    if len(edges) > best_edges:
        best_edges = len(edges)
        if len(edges) >= min_edges:
            print(f"Restart {restart}: found graph with {len(edges)} edges, girth {girth(graph)}")
            best_graph = [set(s) for s in graph]
            break

    if restart % 1000 == 0:
        print(f"Restart {restart}, best so far: {best_edges}")

print(f"Final best edges: {best_edges}")
if best_graph:
    edge_list = []
    for u in range(n):
        for v in best_graph[u]:
            if u < v:
                edge_list.append((u, v))
    print("Edges:", sorted(edge_list))
    print("Number of edges:", len(edge_list))

    # Verify girth
    g = girth(best_graph)
    print("Girth:", g)

    # Verify 3-colorable (should be true by construction)
    print("Colors used:", colors)
    for u in range(n):
        for v in best_graph[u]:
            assert colors[u] != colors[v]
    print("3-colorable: True")

