from collections import deque

n = 19
min_edges = 28

# Edge variables
e = {}
for i in range(n):
    for j in range(i+1, n):
        e[(i,j)] = Bool(f'e_{i}_{j}')

# Color variables
c = [Int(f'c_{i}') for i in range(n)]

solver = Solver()

# Color constraints: each vertex has color 0, 1, or 2
for i in range(n):
    solver.add(Or(c[i] == 0, c[i] == 1, c[i] == 2))

# Edge implies different colors
for i in range(n):
    for j in range(i+1, n):
        solver.add(Implies(e[(i,j)], c[i] != c[j]))

# At least min_edges edges
solver.add(Sum([If(e[(i,j)], 1, 0) for i in range(n) for j in range(i+1, n)]) >= min_edges)

def get_graph(model):
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            if is_true(model.eval(e[(i,j)])):
                edges.append((i, j))
    return edges

def girth_from_edges(edges):
    graph = [set() for _ in range(n)]
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    best = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if v == parent[u]:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
        if best == 3:
            return 3
    return best if best != float('inf') else float('inf')

def find_short_cycle(edges):
    """Find a cycle of length < 7, return list of edges in the cycle."""
    graph = [set() for _ in range(n)]
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if v == parent[u]:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 7:
                        # Reconstruct cycle
                        cycle_edges = []
                        # Path from start to u
                        path_u = []
                        cur = u
                        while cur != -1:
                            path_u.append(cur)
                            cur = parent[cur]
                        path_u.reverse()
                        # Path from start to v
                        path_v = []
                        cur = v
                        while cur != -1:
                            path_v.append(cur)
                            cur = parent[cur]
                        path_v.reverse()
                        # Find common prefix
                        common = 0
                        while common < len(path_u) and common < len(path_v) and path_u[common] == path_v[common]:
                            common += 1
                        common -= 1
                        # Cycle is path_u[common:] + path_v[common:][::-1]
                        cycle_vertices = path_u[common:] + path_v[common+1:][::-1]
                        for i in range(len(cycle_vertices)):
                            a, b = cycle_vertices[i], cycle_vertices[(i+1)%len(cycle_vertices)]
                            cycle_edges.append(tuple(sorted((a, b))))
                        return cycle_edges
    return None

# CEGAR loop
max_iterations = 1000
for iteration in range(max_iterations):
    if solver.check() == sat:
        model = solver.model()
        edges = get_graph(model)
        g = girth_from_edges(edges)
        print(f"Iteration {iteration}: {len(edges)} edges, girth {g}")
        if g >= 7:
            print("Found valid graph!")
            print("Edges:", sorted(edges))
            colors = [model.eval(c[i]).as_long() for i in range(n)]
            print("Colors:", colors)
            break
        else:
            cycle = find_short_cycle(edges)
            if cycle:
                # Forbid this cycle: at least one edge must be absent
                solver.add(Or([Not(e[edge]) for edge in cycle]))
                print(f"  Added constraint to forbid cycle of length {len(cycle)}: {cycle}")
            else:
                print("  ERROR: girth < 7 but no short cycle found")
                break
    else:
        print(f"UNSAT at iteration {iteration}")
        break
else:
    print("Reached max iterations")

